<?php
/**
 * AI analysis server (the "thinking" Gemini proxy) — ships INSIDE the plugin.
 *
 * The plugin contains BOTH the client (SWI_AI) and this server. The server
 * exposes a REST endpoint that accepts product HTML and returns a scraping
 * profile generated by Gemini in reasoning ("thinking") mode.
 *
 * This is the same logic that previously lived as a standalone analyze.php on
 * a customer domain; it now lives in the plugin so it is versioned, shipped
 * and deployed together with everything else.
 *
 * Security: the Gemini API key and the bearer token are NOT hardcoded and NOT
 * stored in the database by default. They are read, in priority order, from:
 *   1. a PHP constant defined in wp-config.php  (SWI_GEMINI_API_KEY / SWI_AI_TOKEN)
 *   2. a plugin option                          (gemini_api_key / ai_token)
 *   3. an (optional) secret file outside the web root
 * Only the one designated server instance needs these; every other store just
 * calls it via SWI_AI.
 *
 * @package SWI
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

class SWI_AI_Server {

	const MODEL   = 'gemini-3-flash-preview';
	const API_URL = 'https://generativelanguage.googleapis.com/v1beta/models/';
	const MAX_HTML = 300000;

	/**
	 * Register the REST route.
	 */
	public static function register() {
		add_action( 'rest_api_init', array( __CLASS__, 'register_route' ) );
	}

	/**
	 * Define the endpoint: POST /wp-json/swi/v1/analyze.
	 */
	public static function register_route() {
		register_rest_route(
			'swi/v1',
			'/analyze',
			array(
				'methods'             => 'POST',
				'callback'            => array( __CLASS__, 'handle' ),
				'permission_callback' => array( __CLASS__, 'authorize' ),
			)
		);
	}

	/**
	 * Authorize the request via a static bearer token.
	 *
	 * @return bool
	 */
	public static function authorize() {
		$token = self::token();
		if ( '' === $token ) {
			return false;
		}

		$auth = isset( $_SERVER['HTTP_AUTHORIZATION'] ) ? $_SERVER['HTTP_AUTHORIZATION'] : '';
		if ( '' === $auth && isset( $_SERVER['REDIRECT_HTTP_AUTHORIZATION'] ) ) {
			$auth = $_SERVER['REDIRECT_HTTP_AUTHORIZATION'];
		}

		return ( $auth === 'Bearer ' . $token );
	}

	/**
	 * Handle the request: analyze HTML and return a scraping profile.
	 *
	 * @param WP_REST_Request $request Request.
	 * @return WP_REST_Response|WP_Error
	 */
	public static function handle( $request ) {
		$api_key = self::api_key();
		if ( '' === $api_key ) {
			return new WP_Error( 'swi_ai_unconfigured', __( 'AI key not configured on this server.', 'swi' ), array( 'status' => 503 ) );
		}

		$html_simple   = (string) $request->get_param( 'html_simple' );
		$html_variable = (string) $request->get_param( 'html_variable' );
		$html_single   = (string) $request->get_param( 'html' );

		if ( '' === $html_simple && '' === $html_variable && '' === $html_single ) {
			return new WP_Error( 'swi_ai_empty', __( 'Provide html, html_simple and/or html_variable.', 'swi' ), array( 'status' => 400 ) );
		}

		$prompt = self::build_prompt( $html_simple, $html_variable, $html_single );

		$payload = array(
			'contents'         => array(
				array(
					'parts' => array( array( 'text' => $prompt ) ),
				),
			),
			'generationConfig' => array(
				'responseMimeType' => 'application/json',
				'temperature'      => 0.1,
				'maxOutputTokens'  => 16384,
				'thinkingConfig'   => array(
					'thinkingBudget' => 8192,
				),
			),
		);

		$url      = self::API_URL . self::MODEL . ':generateContent?key=' . rawurlencode( $api_key );
		$response = wp_remote_post(
			$url,
			array(
				'timeout'     => 180,
				'headers'     => array( 'Content-Type' => 'application/json' ),
				'body'        => wp_json_encode( $payload ),
				'sslverify'   => true,
			)
		);

		if ( is_wp_error( $response ) ) {
			return new WP_Error( 'swi_ai_network', $response->get_error_message(), array( 'status' => 502 ) );
		}

		$code = (int) wp_remote_retrieve_response_code( $response );
		$body = wp_remote_retrieve_body( $response );
		$data = json_decode( $body, true );

		if ( $code >= 400 || ! is_array( $data ) ) {
			$msg = isset( $data['error']['message'] ) ? $data['error']['message'] : ( 'HTTP ' . $code );
			return new WP_Error( 'swi_ai_' . $code, $msg, array( 'status' => 502 ) );
		}

		$text = '';
		if ( isset( $data['candidates'][0]['content']['parts'] ) && is_array( $data['candidates'][0]['content']['parts'] ) ) {
			foreach ( $data['candidates'][0]['content']['parts'] as $part ) {
				if ( isset( $part['text'] ) ) {
					$text .= $part['text'];
				}
			}
		}

		$profile = json_decode( $text, true );
		if ( ! is_array( $profile ) ) {
			return new WP_Error( 'swi_ai_json', __( 'AI returned invalid JSON.', 'swi' ), array( 'status' => 502 ) );
		}

		return rest_ensure_response(
			array(
				'success' => true,
				'profile' => $profile,
			)
		);
	}

	/**
	 * Resolve the Gemini API key.
	 *
	 * @return string
	 */
	private static function api_key() {
		if ( defined( 'SWI_GEMINI_API_KEY' ) && '' !== SWI_GEMINI_API_KEY ) {
			return (string) SWI_GEMINI_API_KEY;
		}

		$key = SWI_Plugin::get_option( 'gemini_api_key', '' );
		return '' !== $key ? $key : '';
	}

	/**
	 * Resolve the bearer token.
	 *
	 * @return string
	 */
	private static function token() {
		if ( defined( 'SWI_AI_TOKEN' ) && '' !== SWI_AI_TOKEN ) {
			return (string) SWI_AI_TOKEN;
		}

		$token = SWI_Plugin::get_option( 'ai_token', '' );
		return '' !== $token ? $token : '';
	}

	/**
	 * Build the reasoning prompt from the sample HTML.
	 *
	 * @param string $html_simple   Simple product HTML.
	 * @param string $html_variable Variable product HTML.
	 * @param string $html_single   Single (unlabeled) product HTML.
	 * @return string
	 */
	private static function build_prompt( $html_simple, $html_variable, $html_single ) {
		$lines = array(
			'Analyze the HTML of an e-commerce product page and produce a "scraping profile" describing how to extract product data from ANY product page on this same site.',
			'',
			'Return ONLY a single JSON object (no markdown, no commentary) with this shape:',
			'{',
			'  "fields": {',
			'    "title": <rule>, "short_description": <rule>, "description": <rule>, "price": <rule>, "sale_price": <rule>, "currency": <rule>, "sku": <rule>, "images": <rule>, "categories": <rule>',
			'  },',
			'  "variable": { "detection": {"strategy":"selector","selector":"<css>"}, "variants": { ... } }',
			'}',
			'',
			'FIELD RULE — one of:',
			'  {"strategy":"meta","key":"<meta property/name>"}',
			'  {"strategy":"jsonld","path":"<dot path into the schema.org Product/ProductGroup node, e.g. sku, offers.price, hasVariant[0].offers.price>"}',
			'  {"strategy":"selector","selector":"<css>"}  // optionally + "attribute":"src|content|data-*"',
			'  {"strategy":"selector_all","selector":"<css>","attribute":"src"}  // list result (images)',
			'  {"strategy":"jsonld_all","path":"<dot path into a list, e.g. itemListElement.name>"}  // list result',
			'  {"strategy":"regex","pattern":"<regex with 1 capture group>"}',
			'  null if you cannot determine a field.',
			'',
			'VARIABLE PRODUCTS — include "variable" only if the site has variants. Strategies:',
			'  {"strategy":"productgroup","attribute_names":["Color","Size"],"option_paths":["color","size"],"price_path":"offers.price","sku_path":"sku","image_path":"image","divide_by":1}  // schema.org ProductGroup.hasVariant',
			'  {"strategy":"embedded_json","selector":"<script/element css>","attribute":"<data-* attr, omit for script>","json_path":"<dot path to variants array, e.g. offers or variant; use $ for the whole object>","attribute_mode":"title_split|option_fields|attributes_map|name_attr","attribute_names":[...],"option_paths":[...],"price_path":"...","sku_path":"...","image_path":"...","stock_path":"...","divide_by":1}',
			'  {"strategy":"dom_options","selector":"<variant <select> css>","attribute_names":["<name>"]}',
			'',
			'ATTRIBUTE_MODE (embedded_json) — pick exactly one:',
			'  - "attributes_map": each variant item has an "attributes" map (WooCommerce-style).',
			'  - "title_split": each variant item has a "title" like "Small / Red" (split on " / ").',
			'  - "option_fields": each item has option1/option2/option3 fields, OR use "option_paths" to point at named fields.',
			'  - "name_attr": schema.org "offers" arrays where each offer is a variant distinguished by its "name" (e.g. "DIOR Sauvage 200 ml", "Avène … shade Sable - Beige 10 g"). Use json_path "offers" + price_path "price" + sku_path "sku" + image_path "image".',
			'',
			'RULES:',
			'- Reason carefully about the HTML structure; prefer JSON-LD and <meta> tags when present (most reliable).',
			'- Never use hashed/obfuscated CSS classes (random-looking names like "sh1mya3") — they change on every deploy. Prefer JSON-LD paths, <meta>, or stable structural selectors.',
			'- For "images": prefer the JSON-LD Product "image" array ({"strategy":"jsonld","path":"image"}) when present. Otherwise selector_all on the PRODUCT GALLERY container (e.g. "#product-gallery img", ".fotorama img", ".woocommerce-product-gallery img", ".product__media img", ".gallery img") with "attribute":"src". Never a generic class shared by logos/icons/related products.',
			'- For "categories": when a BreadcrumbList exists, the names are usually nested under "item" — use jsonld_all path "itemListElement.item.name" (NOT "itemListElement.name"). Else selector_all on breadcrumb <a> links.',
			'- CSS must be standard (tag, .class, #id, [attr], [attr="v"], descendant/child, comma). No :contains()/:has()/:not().',
			'- Variable detection: prefer {"strategy":"jsonld_offers"} when the Product JSON-LD has an "offers" array of >1 (each offer = a variant). Only fall back to a "selector" presence check when there is no JSON-LD offers array.',
			'',
		);

		if ( '' !== $html_single ) {
			$lines[] = 'This is a single product page (simple OR variable). Build a profile that handles BOTH — detect variable products via JSON-LD offers arrays, ProductGroup.hasVariant, or an embedded variant JSON.';
			$lines[] = '';
			$lines[] = '=== PRODUCT HTML ===';
			$lines[] = substr( $html_single, 0, self::MAX_HTML );
		} else {
			if ( '' !== $html_simple ) {
				$lines[] = '=== SIMPLE PRODUCT HTML ===';
				$lines[] = substr( $html_simple, 0, self::MAX_HTML );
				$lines[] = '';
			}
			if ( '' !== $html_variable ) {
				$lines[] = '=== VARIABLE PRODUCT HTML ===';
				$lines[] = substr( $html_variable, 0, self::MAX_HTML );
			}
		}

		return implode( "\n", $lines );
	}
}
